/**
 * Сырые импорты Vite: `import x from './file.html?raw'` (TRIP-478).
 *
 * ★ ЗАЧЕМ. Суффикс `?raw` — механизм сборщика: Vite отдаёт содержимое файла
 * строкой. TypeScript о нём не знает, а штатные типы `vite/client`, где он
 * объявлен, в проекте не подключены намеренно (`"types": []` в jsconfig —
 * иначе в проверку въезжает всё окружение сборщика). Поэтому объявляем ровно
 * то, чем пользуемся, и ничего сверх.
 *
 * Носитель сегодня один: витрина `/kit` показывает разметку экрана запуска
 * (`src/design/splash.html`) — тот же файл, что сборка подставляет в документ.
 * Читать его строкой, а не переписывать компонентом, — решение против второй
 * копии; типу об этом знать не нужно, ему хватает «это строка».
 *
 * Границы: объявление не проверяет ни существование файла, ни его содержимое.
 * Оно снимает ровно ошибку разрешения модуля и ничего больше.
 */
declare module '*.html?raw' {
  const content: string;
  export default content;
}
